extern "C" int strlen(const char *);

class string_buf {
public:
    int char_length;
};

class stringx {
    char *characters;
    string_buf *my_buf;
public:
    stringx();
    stringx(const stringx &);
    ~stringx();
    void make_room(int);
    void append(const stringx &);
    void append(const char *, int);
    friend stringx operator+(const stringx &, const stringx &);
    friend stringx operator+(const char *, const stringx &);
    friend stringx operator+(const stringx &, const char *);
};

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
    stringx foo;
    foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs);
    return foo;
}

inline stringx operator+(const char *lhs, const stringx &rhs)
{
    stringx foo;
    int len = strlen(lhs);
    foo.make_room(len + rhs.my_buf->char_length);
    foo.append(lhs, len);
    foo.append(rhs);
    return foo;
}

inline stringx operator+(const stringx &lhs, const char *rhs)
{
    stringx foo;
    int len = strlen(rhs);
    foo.make_room(lhs.my_buf->char_length + len);
    foo.append(lhs);
    foo.append(rhs, len);
    return foo;
}

class vector3d {
