    const vm_executable *get_executable() const;
};

class vm_stack {
public:
    int salloc;
    char *buffer;
    char *SP;
private:
    vm_thread *my_thread;
public:
    char *get_SP() const { return SP; }
    void pop(int n) { SP -= n; }
    vm_thread *get_thread() const { return my_thread; }
    bool push(const char *, int);
};

